create table if not exists public.intelligence_business_profiles (
  studio_id uuid primary key references public.visibility_studios(id) on delete cascade,
  business_type text not null default 'tattoo_studio', industry text, subindustry text, business_model text,
  currency text not null default 'GBP' check (char_length(currency) = 3), timezone text not null default 'Europe/London',
  metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.intelligence_growth_diagnostics (
  id uuid primary key default gen_random_uuid(), studio_id uuid not null references public.visibility_studios(id) on delete cascade,
  diagnostic_version text not null default 'three-lever-v1', period_start date not null, period_end date not null,
  baseline_revenue_pence bigint, unique_customers numeric, transactions numeric, purchase_frequency numeric, average_transaction_value_pence bigint,
  customer_opportunity_pence bigint, frequency_opportunity_pence bigint, atv_opportunity_pence bigint,
  primary_lever text check (primary_lever is null or primary_lever in ('customers','frequency','average_transaction_value')),
  constraints jsonb not null default '[]'::jsonb, assumptions jsonb not null default '[]'::jsonb, evidence_ids uuid[] not null default '{}',
  confidence numeric check (confidence is null or confidence between 0 and 1), status text not null default 'draft' check (status in ('draft','measured','scored','superseded')),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (period_end >= period_start)
);
create table if not exists public.intelligence_opportunity_scoring_versions (
  key text primary key, name text not null, description text, weights jsonb not null,
  status text not null default 'active' check (status in ('draft','active','deprecated')), created_at timestamptz not null default now()
);
create table if not exists public.intelligence_playbooks (
  id uuid primary key default gen_random_uuid(), key text not null, version integer not null default 1 check (version > 0), name text not null,
  lever text not null check (lever in ('customers','frequency','average_transaction_value')), category text not null, hypothesis text not null, trigger_description text not null,
  required_metric_keys jsonb not null default '[]'::jsonb, action_steps jsonb not null default '[]'::jsonb, primary_metric_key text not null,
  guardrail_metric_keys jsonb not null default '[]'::jsonb, expected_time_to_signal_days integer check (expected_time_to_signal_days is null or expected_time_to_signal_days > 0),
  effort_score integer not null default 3 check (effort_score between 1 and 5), risk_score integer not null default 2 check (risk_score between 1 and 5),
  status text not null default 'active' check (status in ('draft','active','deprecated')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (key, version)
);
create table if not exists public.intelligence_opportunity_scores (
  id uuid primary key default gen_random_uuid(), studio_id uuid not null references public.visibility_studios(id) on delete cascade,
  diagnostic_id uuid references public.intelligence_growth_diagnostics(id) on delete cascade, diagnosis_id uuid references public.intelligence_diagnoses(id) on delete set null,
  playbook_id uuid references public.intelligence_playbooks(id) on delete set null, lever text not null check (lever in ('customers','frequency','average_transaction_value')),
  title text not null, opportunity_value_pence bigint, impact_score numeric not null check (impact_score between 0 and 100),
  evidence_strength_score numeric not null check (evidence_strength_score between 0 and 100), confidence_score numeric not null check (confidence_score between 0 and 100),
  ease_score numeric not null check (ease_score between 0 and 100), speed_score numeric not null check (speed_score between 0 and 100), strategic_fit_score numeric not null check (strategic_fit_score between 0 and 100),
  feasibility_score numeric not null check (feasibility_score between 0 and 100), learning_value_score numeric not null check (learning_value_score between 0 and 100),
  total_score numeric generated always as (impact_score * 0.30 + evidence_strength_score * 0.10 + confidence_score * 0.10 + ease_score * 0.15 + speed_score * 0.10 + strategic_fit_score * 0.10 + feasibility_score * 0.10 + learning_value_score * 0.05) stored,
  scoring_version text not null default 'growth-opportunity-v1' references public.intelligence_opportunity_scoring_versions(key), rationale text, evidence_ids uuid[] not null default '{}',
  status text not null default 'candidate' check (status in ('candidate','prioritised','recommended','dismissed','completed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
alter table public.intelligence_recommendations add column if not exists playbook_id uuid references public.intelligence_playbooks(id) on delete set null, add column if not exists opportunity_score_id uuid references public.intelligence_opportunity_scores(id) on delete set null, add column if not exists primary_metric_key text, add column if not exists target_value numeric, add column if not exists measurement_window_days integer check (measurement_window_days is null or measurement_window_days > 0);
create index if not exists idx_growth_diagnostics_studio_period on public.intelligence_growth_diagnostics(studio_id, period_end desc);
create index if not exists idx_opportunity_scores_studio_score on public.intelligence_opportunity_scores(studio_id, total_score desc);
create index if not exists idx_playbooks_lever_status on public.intelligence_playbooks(lever, status);
create index if not exists idx_recommendations_playbook on public.intelligence_recommendations(playbook_id);
alter table public.intelligence_business_profiles enable row level security;
alter table public.intelligence_growth_diagnostics enable row level security;
alter table public.intelligence_opportunity_scoring_versions enable row level security;
alter table public.intelligence_playbooks enable row level security;
alter table public.intelligence_opportunity_scores enable row level security;
create policy "business profiles tenant access" on public.intelligence_business_profiles for all to authenticated using (exists (select 1 from public.studio_members m where m.studio_id = intelligence_business_profiles.studio_id and m.user_id = (select auth.uid()) and m.active)) with check (exists (select 1 from public.studio_members m where m.studio_id = intelligence_business_profiles.studio_id and m.user_id = (select auth.uid()) and m.active));
create policy "growth diagnostics tenant access" on public.intelligence_growth_diagnostics for all to authenticated using (exists (select 1 from public.studio_members m where m.studio_id = intelligence_growth_diagnostics.studio_id and m.user_id = (select auth.uid()) and m.active)) with check (exists (select 1 from public.studio_members m where m.studio_id = intelligence_growth_diagnostics.studio_id and m.user_id = (select auth.uid()) and m.active));
create policy "opportunity scores tenant access" on public.intelligence_opportunity_scores for all to authenticated using (exists (select 1 from public.studio_members m where m.studio_id = intelligence_opportunity_scores.studio_id and m.user_id = (select auth.uid()) and m.active)) with check (exists (select 1 from public.studio_members m where m.studio_id = intelligence_opportunity_scores.studio_id and m.user_id = (select auth.uid()) and m.active));
create policy "scoring versions authenticated read" on public.intelligence_opportunity_scoring_versions for select to authenticated using (status <> 'deprecated');
create policy "playbooks authenticated read" on public.intelligence_playbooks for select to authenticated using (status <> 'deprecated');
revoke all on public.intelligence_business_profiles, public.intelligence_growth_diagnostics, public.intelligence_opportunity_scoring_versions, public.intelligence_playbooks, public.intelligence_opportunity_scores from anon;
grant select, insert, update, delete on public.intelligence_business_profiles, public.intelligence_growth_diagnostics, public.intelligence_opportunity_scores to authenticated;
grant select on public.intelligence_opportunity_scoring_versions, public.intelligence_playbooks to authenticated;
insert into public.intelligence_opportunity_scoring_versions (key,name,description,weights) values ('growth-opportunity-v1','Growth Opportunity Score V1','Deterministic 0-100 priority score. Economic impact cannot hide weak evidence or confidence.','{"impact":0.30,"evidence_strength":0.10,"confidence":0.10,"ease":0.15,"speed":0.10,"strategic_fit":0.10,"feasibility":0.10,"learning_value":0.05}'::jsonb) on conflict (key) do update set name=excluded.name,description=excluded.description,weights=excluded.weights,status='active';
insert into public.intelligence_metric_definitions (key,name,description,unit,classification,version,formula,status) values
('revenue','Revenue','Realised revenue during the measurement period.','GBP','observed',1,null,'active'),('unique_customers','Unique Customers','Distinct paying customers during the period.','customers','observed',1,null,'active'),('transactions','Transactions','Completed revenue-generating transactions during the period.','transactions','observed',1,null,'active'),('average_transaction_value','Average Transaction Value','Revenue divided by completed transactions.','GBP/transaction','derived',1,'revenue / transactions','active'),('purchase_frequency','Purchase Frequency','Completed transactions divided by unique paying customers.','transactions/customer','derived',1,'transactions / unique_customers','active'),('leads','Leads','Distinct prospective customers entering the measurable funnel.','leads','observed',1,null,'active'),('qualified_leads','Qualified Leads','Leads meeting the business qualification rule.','leads','observed',1,null,'active'),('new_customers','New Customers','First-time paying customers during the period.','customers','observed',1,null,'active'),('repeat_customers','Repeat Customers','Customers meeting the versioned repeat-purchase rule.','customers','derived',1,'Count of customers with repeat transactions in the defined lookback.','active'),('lead_to_customer_conversion_rate','Lead-to-Customer Conversion Rate','New customers divided by qualified leads.','percent','derived',1,'new_customers / qualified_leads','active'),('repeat_customer_rate','Repeat Customer Rate','Repeat customers divided by unique customers.','percent','derived',1,'repeat_customers / unique_customers','active'),('customer_retention_rate','Customer Retention Rate','Customers retained between defined cohorts or periods.','percent','derived',1,'Versioned cohort retention calculation.','active'),('churn_rate','Churn Rate','Customers lost divided by customers eligible to return.','percent','derived',1,'Versioned churn calculation.','active'),('days_to_second_purchase','Days to Second Purchase','Median elapsed days between first and second completed transaction.','days','derived',1,'Median(second_transaction_at - first_transaction_at).','active'),('customer_lifetime_value','Customer Lifetime Value','Versioned realised or modelled customer lifetime value.','GBP/customer','modelled',1,'Must declare realised vs modelled lineage.','active'),('gross_profit','Gross Profit','Revenue less direct cost of goods or services.','GBP','derived',1,'revenue - direct_cost','active'),('gross_margin_rate','Gross Margin Rate','Gross profit divided by revenue.','percent','derived',1,'gross_profit / revenue','active'),('price_realisation_rate','Price Realisation Rate','Realised selling price divided by reference/list price.','percent','derived',1,'realised_price / reference_price','active'),('refund_rate','Refund Rate','Refunded value divided by gross transaction value.','percent','derived',1,'refunded_value / gross_transaction_value','active'),('capacity_units','Capacity Units','Available productive capacity during the period.','units','observed',1,null,'active'),('booked_capacity_units','Booked Capacity Units','Productive capacity committed to customer work.','units','observed',1,null,'active'),('capacity_utilisation_rate','Capacity Utilisation Rate','Booked productive capacity divided by available productive capacity.','percent','derived',1,'booked_capacity_units / capacity_units','active'),('cancellation_rate','Cancellation Rate','Cancelled committed transactions divided by scheduled transactions.','percent','derived',1,'cancelled_transactions / scheduled_transactions','active'),('no_show_rate','No-show Rate','No-show transactions divided by scheduled transactions.','percent','derived',1,'no_show_transactions / scheduled_transactions','active'),('customer_acquisition_cost','Customer Acquisition Cost','Attributable acquisition spend divided by new customers.','GBP/customer','derived',1,'attributable_acquisition_spend / new_customers','active'),('customer_growth_opportunity','Customer Growth Opportunity','Modelled independent revenue opportunity from additional paying customers.','GBP','modelled',1,'delta_customers * purchase_frequency * average_transaction_value','active'),('frequency_growth_opportunity','Frequency Growth Opportunity','Modelled independent revenue opportunity from increased purchase frequency.','GBP','modelled',1,'unique_customers * delta_frequency * average_transaction_value','active'),('atv_growth_opportunity','ATV Growth Opportunity','Modelled independent revenue opportunity from increased average transaction value.','GBP','modelled',1,'unique_customers * purchase_frequency * delta_average_transaction_value','active') on conflict (key,version) do update set name=excluded.name,description=excluded.description,unit=excluded.unit,classification=excluded.classification,formula=excluded.formula,status=excluded.status,updated_at=now();
insert into public.intelligence_playbooks (key,version,name,lever,category,hypothesis,trigger_description,required_metric_keys,action_steps,primary_metric_key,guardrail_metric_keys,expected_time_to_signal_days,effort_score,risk_score,status) values
('lead_response_speed',1,'Lead Response Speed','customers','conversion','Reducing avoidable response delay increases the share of qualified enquiries that become customers.','Qualified lead volume exists and response delay is material or unmeasured.','["qualified_leads","lead_to_customer_conversion_rate"]'::jsonb,'["Measure current response-time distribution","Define response SLA","Automate acknowledgement and owner assignment","Measure conversion by response-time band"]'::jsonb,'lead_to_customer_conversion_rate','["customer_acquisition_cost"]'::jsonb,30,2,1,'active'),
('missed_enquiry_recovery',1,'Missed Enquiry Recovery','customers','conversion','Systematically recovering unanswered enquiries converts demand already paid for or earned.','Evidence shows abandoned, unanswered or unworked enquiries.','["leads","qualified_leads","lead_to_customer_conversion_rate"]'::jsonb,'["Define missed-enquiry state","Build recovery queue","Contact with context-aware follow-up","Measure recovered customers"]'::jsonb,'new_customers','["customer_acquisition_cost"]'::jsonb,30,2,1,'active'),
('lead_followup_sequence',1,'Lead Follow-up Sequence','customers','conversion','A structured multi-touch sequence improves conversion where qualified leads do not decide immediately.','Qualified leads materially exceed new customers and follow-up is inconsistent.','["qualified_leads","new_customers","lead_to_customer_conversion_rate"]'::jsonb,'["Segment lead intent","Define follow-up cadence","Deliver value-based sequence","Measure incremental conversion"]'::jsonb,'lead_to_customer_conversion_rate','["customer_acquisition_cost"]'::jsonb,45,3,2,'active'),
('quote_followup',1,'Quote Follow-up','customers','conversion','High-intent quoted prospects have greater recoverable value than cold acquisition.','Quotes/proposals are issued but a material share do not convert.','["qualified_leads","lead_to_customer_conversion_rate"]'::jsonb,'["Create open-quote queue","Classify objection/loss reason","Run timed follow-up","Measure quote-to-customer conversion"]'::jsonb,'lead_to_customer_conversion_rate','[]'::jsonb,30,2,1,'active'),
('referral_engine',1,'Referral Engine','customers','referral','Satisfied customers can create lower-cost qualified demand when referral behaviour is deliberately designed.','Repeat/retained customers exist but referral capture is absent or ad hoc.','["unique_customers","repeat_customer_rate","new_customers"]'::jsonb,'["Define referral moment","Create referral ask","Track source and referred customer","Compare CAC and conversion"]'::jsonb,'new_customers','["customer_acquisition_cost","customer_retention_rate"]'::jsonb,90,3,2,'active'),
('local_visibility_capture',1,'Local Visibility Capture','customers','acquisition','Improving high-intent local discovery and conversion paths can increase qualified demand.','Observed local demand exists and visibility or conversion path is weak.','["demand","leads"]'::jsonb,'["Identify high-intent local queries","Prioritise visibility gaps","Improve landing conversion path","Measure attributable leads/customers"]'::jsonb,'new_customers','["customer_acquisition_cost"]'::jsonb,90,4,2,'active'),
('lapsed_lead_reactivation',1,'Lapsed Lead Reactivation','customers','reactivation','Qualified historical leads can be cheaper to reactivate than new demand is to acquire.','A permissioned historical lead pool exists with known non-conversion.','["qualified_leads","new_customers"]'::jsonb,'["Define eligible lapsed cohort","Exclude invalid/suppressed leads","Run reactivation offer/message","Measure reactivated customers"]'::jsonb,'new_customers','["customer_acquisition_cost"]'::jsonb,45,3,2,'active'),
('cancellation_backfill',1,'Cancellation Backfill','customers','capacity_recovery','Released capacity can be monetised by matching it to ready qualified demand.','Cancellation creates sellable capacity and a suitable waitlist/lead pool exists.','["cancellation_rate","qualified_leads","capacity_utilisation_rate"]'::jsonb,'["Detect released capacity","Rank eligible customers/leads","Offer slot with guardrails","Measure recovered transactions/revenue"]'::jsonb,'transactions','["average_transaction_value"]'::jsonb,30,3,2,'active'),
('next_booking_at_checkout',1,'Next Booking at Checkout','frequency','rebooking','Securing the next relevant transaction before the current journey ends increases repeat frequency.','Customers have a natural next transaction but rebooking is low or unmeasured.','["purchase_frequency","repeat_customer_rate"]'::jsonb,'["Define eligible next action","Prompt at completion/checkout","Make booking low-friction","Measure repeat frequency"]'::jsonb,'purchase_frequency','["cancellation_rate","no_show_rate"]'::jsonb,90,2,1,'active'),
('dormant_customer_reactivation',1,'Dormant Customer Reactivation','frequency','reactivation','Customers who are overdue relative to their normal cadence can be reactivated more efficiently than cold prospects.','A customer cohort exists beyond an evidence-based dormancy threshold.','["unique_customers","purchase_frequency","days_to_second_purchase"]'::jsonb,'["Define dormancy threshold","Build eligible cohort","Run relevant reactivation message","Measure repeat transactions"]'::jsonb,'purchase_frequency','["customer_retention_rate"]'::jsonb,60,3,2,'active'),
('maintenance_rebooking',1,'Maintenance Rebooking','frequency','retention','Recurring needs convert into predictable frequency when the correct cadence is operationalised.','The product/service has a genuine recurring maintenance cadence.','["purchase_frequency","days_to_second_purchase"]'::jsonb,'["Determine observed cadence","Create due-date logic","Send reminder/booking path","Measure repeat transactions"]'::jsonb,'purchase_frequency','["cancellation_rate"]'::jsonb,120,3,1,'active'),
('milestone_followup',1,'Milestone Follow-up','frequency','retention','Lifecycle milestones create relevant moments for the next transaction.','A measurable completion or lifecycle milestone predicts future demand.','["purchase_frequency","repeat_customer_rate"]'::jsonb,'["Identify predictive milestone","Define next-best action","Trigger follow-up","Measure milestone-to-repeat conversion"]'::jsonb,'repeat_customer_rate','[]'::jsonb,90,3,1,'active'),
('membership_frequency',1,'Membership / Continuity Frequency','frequency','continuity','A continuity offer can increase frequency when repeated demand and unit economics already exist.','Observed repeat demand exists and a membership does not manufacture unwanted usage.','["purchase_frequency","repeat_customer_rate","gross_margin_rate"]'::jsonb,'["Validate repeat demand","Design continuity economics","Pilot with eligible cohort","Measure frequency and margin"]'::jsonb,'purchase_frequency','["gross_margin_rate","customer_retention_rate"]'::jsonb,180,4,3,'active'),
('post_purchase_nurture',1,'Post-purchase Nurture','frequency','retention','Relevant education and next-best-action follow-up increases the probability of a second transaction.','First-time customers materially outnumber repeat customers and follow-up is weak.','["new_customers","repeat_customer_rate","days_to_second_purchase"]'::jsonb,'["Map post-purchase journey","Define value-led touchpoints","Trigger next-best action","Measure second-purchase rate"]'::jsonb,'repeat_customer_rate','["customer_retention_rate"]'::jsonb,120,3,1,'active'),
('seasonal_reactivation',1,'Seasonal Reactivation','frequency','reactivation','Known seasonal intent can create incremental repeat purchases when timed to real demand.','Historical demand shows a recurring seasonal/event pattern.','["purchase_frequency","transactions"]'::jsonb,'["Validate seasonal pattern","Define eligible customer cohort","Run timed campaign","Compare to prior/control period"]'::jsonb,'transactions','["average_transaction_value"]'::jsonb,90,3,2,'active'),
('client_recall',1,'Customer Recall','frequency','retention','Proactive recall of customers overdue relative to their own/segment cadence increases repeat transactions.','Customer-level transaction history supports an expected return window.','["purchase_frequency","days_to_second_purchase","unique_customers"]'::jsonb,'["Model expected return window","Generate overdue list","Prioritise by value/fit","Measure recalled transactions"]'::jsonb,'purchase_frequency','["customer_retention_rate"]'::jsonb,90,3,2,'active'),
('price_floor_review',1,'Price Floor Review','average_transaction_value','pricing','Eliminating systematically uneconomic low-value transactions can improve realised transaction value and margin.','Observed transactions fall below a defensible economic floor.','["average_transaction_value","gross_margin_rate","price_realisation_rate"]'::jsonb,'["Calculate economic floor","Segment below-floor work","Define exceptions","Measure ATV, margin and conversion"]'::jsonb,'average_transaction_value','["lead_to_customer_conversion_rate","gross_margin_rate"]'::jsonb,90,3,3,'active'),
('package_bundling',1,'Package Bundling','average_transaction_value','offer','Combining complementary value into a coherent package can increase transaction value without arbitrary discounting.','Customers commonly buy complementary scope separately or leave value unpurchased.','["average_transaction_value","transactions"]'::jsonb,'["Identify complementary scope","Design package economics","Test package presentation","Measure ATV and take rate"]'::jsonb,'average_transaction_value','["gross_margin_rate","lead_to_customer_conversion_rate"]'::jsonb,90,3,2,'active'),
('upsell_addon',1,'Relevant Upsell / Add-on','average_transaction_value','offer','A relevant add-on at the decision point increases transaction value when it improves customer outcome.','A complementary add-on exists with evidence of customer relevance.','["average_transaction_value","transactions"]'::jsonb,'["Identify outcome-relevant add-on","Define eligibility","Present at purchase/booking","Measure attach rate and ATV"]'::jsonb,'average_transaction_value','["gross_margin_rate","refund_rate"]'::jsonb,60,2,2,'active'),
('premium_tier',1,'Premium Tier','average_transaction_value','offer','A differentiated premium option captures willingness to pay that a single undifferentiated offer misses.','Customer segments have materially different value requirements/willingness to pay.','["average_transaction_value","gross_margin_rate"]'::jsonb,'["Identify premium value drivers","Build differentiated tier","Pilot without removing core option","Measure mix, ATV and conversion"]'::jsonb,'average_transaction_value','["lead_to_customer_conversion_rate","gross_margin_rate"]'::jsonb,120,4,3,'active'),
('minimum_booking_value',1,'Minimum Transaction / Booking Value','average_transaction_value','pricing','A minimum economic threshold protects scarce capacity from low-value transactions.','Capacity is constrained and small transactions create disproportionate delivery cost.','["average_transaction_value","capacity_utilisation_rate","gross_margin_rate"]'::jsonb,'["Quantify capacity economics","Set defensible threshold","Define exceptions","Measure ATV, utilisation and conversion"]'::jsonb,'average_transaction_value','["lead_to_customer_conversion_rate","capacity_utilisation_rate"]'::jsonb,90,3,3,'active'),
('scope_based_pricing',1,'Scope-based Pricing','average_transaction_value','pricing','Pricing that reflects complexity/scope reduces systematic underpricing.','Comparable transactions show weak relationship between delivered scope and realised price.','["average_transaction_value","price_realisation_rate","gross_margin_rate"]'::jsonb,'["Define scope drivers","Create pricing bands/rules","Review exceptions","Measure price realisation and margin"]'::jsonb,'price_realisation_rate','["lead_to_customer_conversion_rate","gross_margin_rate"]'::jsonb,120,4,3,'active'),
('cross_sell',1,'Cross-sell','average_transaction_value','offer','Adjacent relevant products/services can increase transaction value and customer outcome.','Existing customers have an evidenced adjacent need.','["average_transaction_value","unique_customers"]'::jsonb,'["Identify adjacent need","Define eligible segment","Present contextual cross-sell","Measure attach rate and ATV"]'::jsonb,'average_transaction_value','["refund_rate","customer_retention_rate"]'::jsonb,90,3,2,'active'),
('value_based_offer_reframe',1,'Value-based Offer Reframe','average_transaction_value','offer','Improving the clarity and certainty of value can support stronger pricing before discounting.','Price resistance is observed but value communication or packaging is weak or inconsistent.','["average_transaction_value","lead_to_customer_conversion_rate","price_realisation_rate"]'::jsonb,'["Capture objection evidence","Clarify outcome/value components","Reframe offer and proof","Measure conversion and price realisation"]'::jsonb,'price_realisation_rate','["lead_to_customer_conversion_rate"]'::jsonb,60,3,2,'active') on conflict (key,version) do update set name=excluded.name,lever=excluded.lever,category=excluded.category,hypothesis=excluded.hypothesis,trigger_description=excluded.trigger_description,required_metric_keys=excluded.required_metric_keys,action_steps=excluded.action_steps,primary_metric_key=excluded.primary_metric_key,guardrail_metric_keys=excluded.guardrail_metric_keys,expected_time_to_signal_days=excluded.expected_time_to_signal_days,effort_score=excluded.effort_score,risk_score=excluded.risk_score,status=excluded.status,updated_at=now();